fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since the array is guaranteed to be non-empty, we can safely iterate
    // We only need to check consecutive elements because:
    // If arr[i] <= arr[i+1] for all i, then by transitivity,
    // arr[i] <= arr[j] for all i < j
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false;
        }
    }
    true
}